  "Erfasst {from}–{to} · {scope}": {"en": "Tracked {from}–{to} · {scope}", "de": "Erfasst {from}–{to} · {scope}", "zh": "已记录 {from}–{to} · {scope}"},
  "deine Zeit": {"en": "your time", "de": "deine Zeit", "zh": "你的工时"},
  "{done}/{total} Aufgaben": {"en": "{done}/{total} tasks", "de": "{done}/{total} Aufgaben", "zh": "{done}/{total} 项任务"},
  "Aufgabe {name} bearbeiten": {"en": "Edit task {name}", "de": "Aufgabe {name} bearbeiten", "zh": "编辑任务 {name}"},
